const getProductsForItems = `-- name: GetProductsForItems :many
SELECT
    p.id AS product_id,
    p.item_id,
    i.sku,
    p.product_line_id
FROM product p
JOIN item i ON i.id = p.item_id
WHERE i.account_id = ?
  AND p.item_id IN (/*SLICE:item_ids*/?)
ORDER BY p.item_id
`

